public class Solution {
    public static boolean isPowerOfTwo(int n) {
        if (n <= 0) return false;
        while (n > 1) {
            if (n % 2 != 0) {
                return false;
            }
            n /= 2;
        }
        return true;
    }

    public static void main(String[] args) {
        int test1 = 64;
        int test2 = 50;
        System.out.println(test1 + " is power of 2: " + isPowerOfTwo(test1));
        System.out.println(test2 + " is power of 2: " + isPowerOfTwo(test2));
    }
}

