public class Solution {
    public static int floorSqrt(int n) {
        if (n < 2) return n;
        long low = 1, high = n / 2;
        long ans = 1;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (mid * mid <= n) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int) ans;
    }

    public static void main(String[] args) {
        int n = 50;
        System.out.println("Input N: " + n);
        System.out.println("Floor sqrt: " + floorSqrt(n));
    }
}

public class Solution {
    public static boolean isPalindrome(int num) {
        if (num < 0 || (num % 10 == 0 && num != 0)) return false;
        int temp = num;
        int reversed = 0;
        while (temp > 0) {
            reversed = (reversed * 10) + (temp % 10);
            temp /= 10;
        }
        return num == reversed;
    }

    public static void main(String[] args) {
        int val1 = 1221;
        int val2 = -121;
        System.out.println(val1 + " is palindrome: " + isPalindrome(val1));
        System.out.println(val2 + " is palindrome: " + isPalindrome(val2));
    }
}

public class Solution {
    public static String toBinary32(int num) {
        StringBuilder sb = new StringBuilder();
        int shift = 31;
        while (shift >= 0) {
            sb.append((num >>> shift) & 1);
            shift--;
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int val = -10;
        System.out.println("Decimal: " + val);
        System.out.println("32-Bit Binary: " + toBinary32(val));
    }
}

