                count++;
            }
            candidate++;
        }
        System.out.println();
    }
}

public class Solution {
    public static double sqrtNewton(double s) {
        if (s < 0) throw new IllegalArgumentException("Negative input");
        if (s == 0) return 0.0;
        double x = s / 2.0;
        double next = 0.5 * (x + s / x);
        double epsilon = 1e-9;

        while (Math.abs(x - next) >= epsilon) {
            x = next;
            next = 0.5 * (x + s / x);
        }
        return next;
    }

    public static void main(String[] args) {
        double val = 612.0;
        double sqrt = sqrtNewton(val);
        System.out.printf("Newton sqrt of %.1f: %.6f%n", val, sqrt);
    }
}

public class Solution {
    public static String toBase(int num, int base) {
        if (base < 2 || base > 16) throw new IllegalArgumentException("Unsupported base");
        if (num == 0) return "0";
        String digits = "0123456789ABCDEF";
        StringBuilder sb = new StringBuilder();
        int temp = num;

        while (temp > 0) {
            sb.append(digits.charAt(temp % base));
            temp /= base;
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        int number = 254;
        System.out.println("Decimal: " + number);
        System.out.println("Hex (Base 16): " + toBase(number, 16));
        System.out.println("Octal (Base 8): " + toBase(number, 8));
        System.out.println("Binary (Base 2): " + toBase(number, 2));
    }
}

public class Solution {
    public static boolean isArmstrong(int num) {
        if (num < 0) return false;
        int temp = num;
        int k = 0;
        while (temp > 0) {
            k++;
            temp /= 10;
        }
        temp = num;
        int sum = 0;
        while (temp > 0) {
            int d = temp % 10;
            int p = 1;
            for (int i = 0; i < k; i++) p *= d;
            sum += p;
            temp /= 10;
        }
        return sum == num;
    }

    public static void main(String[] args) {
        int val = 371;
        System.out.println("Number: " + val);
        System.out.println("Is Armstrong: " + isArmstrong(val));
    }
}

