import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static String fractionToDecimal(int num, int den) {
        if (num == 0) return "0";
        StringBuilder sb = new StringBuilder();
        sb.append(num / den);
        long rem = num % den;
        if (rem == 0) return sb.toString();

        sb.append(".");
        Map<Long, Integer> map = new HashMap<>();
        while (rem != 0) {
            if (map.containsKey(rem)) {
                int index = map.get(rem);
                sb.insert(index, "(");
                sb.append(")");
                break;
            }
            map.put(rem, sb.length());
            rem *= 10;
            sb.append(rem / den);
            rem %= den;
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int num = 1, den = 6;
        System.out.println("Fraction: " + num + "/" + den);
        System.out.println("Decimal:  " + fractionToDecimal(num, den));
    }
}

public class Solution {
    public static String toBase36(long n, int base) {
        if (base < 2 || base > 36) throw new IllegalArgumentException("Radix out of range");
        if (n == 0) return "0";
        StringBuilder sb = new StringBuilder();
        long temp = n;

        while (temp > 0) {
            int rem = (int) (temp % base);
            if (rem < 10) {
                sb.append((char) ('0' + rem));
            } else {
                sb.append((char) ('A' + (rem - 10)));
            }
            temp /= base;
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        long value = 48550L;
        System.out.println("Decimal: " + value);
        System.out.println("Base 36: " + toBase36(value, 36));
    }
}

public class Solution {
    public static void factorize(int n) {
        System.out.print("Prime factors of " + n + ": ");
        while (n % 2 == 0) {
            System.out.print(2 + " ");
            n /= 2;
        }
        int d = 3;
        while (d * d <= n) {
            while (n % d == 0) {
                System.out.print(d + " ");
                n /= d;
            }
            d += 2;
        }
        if (n > 1) {
            System.out.print(n);
        }
        System.out.println();
    }

    public static void main(String[] args) {
        factorize(315);
    }
}

public class Solution {
    public static void main(String[] args) {
        int[] stream = {10, 20, 30, 40, 50};
        int[] buffer = new int[2];
        int size = 0;
        int streamIdx = 0;

        System.out.println("Initial buffer capacity: " + buffer.length);
        while (streamIdx < stream.length) {
            if (size == buffer.length) {
                int newCapacity = buffer.length * 2;
                int[] newBuffer = new int[newCapacity];
                System.arraycopy(buffer, 0, newBuffer, 0, size);
                buffer = newBuffer;
                System.out.println("Capacity exceeded! Resized to: " + buffer.length);
            }
            buffer[size++] = stream[streamIdx++];
        }

        System.out.println("Final buffer size: " + size + " | Total capacity: " + buffer.length);
    }
}
